{
  "similarities": [
    {
      "point": "Both define an engine as a compound machine made of mechanical powers used to produce effects not easily achieved otherwise.",
      "quote_britannica": "ENGINE, Sì mechanics, its a compound machine, made of one or more mechanical powers, as levers, pullies, ferws, &. in order to raise, cat, or fulanany any weight, or produce any effect which could not be easily effected otherwise.",
      "quote_wikipedia": "An engine or motor is a machine designed to convert one or more forms of energy into mechanical energy."
    },
    {
      "point": "Both trace the word engine to French and Latin roots connected with ingenuity.",
      "quote_britannica": "The word is formed of the French reign, from the Latin ingeniums witst by England reason of the ingenuity required in the contrivance of engines to augment the effect of moving powers.",
      "quote_wikipedia": "The word engine derives from Old French engin, from the Latin ingenium –the root of the word ingenious."
    },
    {
      "point": "Both mention steam engines as historically significant examples.",
      "quote_britannica": "States Engins, a machine to raise water by fire, or rather by the force of water turned into fleam. See States Engine.",
      "quote_wikipedia": "The Watt steam engine was the first type of steam engine to make use of steam at a pressure just above atmospheric to drive the piston helped by a partial vacuum."
    },
    {
      "point": "Both associate engines with military applications and siege works.",
      "quote_britannica": "ENGINEEN, in the military arts, an able expert man, who, by a perfect knowledge in mathematics, delineates upon paper, or marks upon the ground, all sorts of forms, and other works proper for officers and defence.",
      "quote_wikipedia": "Pre-industrial weapons of war, such as catapults, trebuchets and battering rams, were called siege engines, and knowledge of how to construct them was often treated as a military secret."
    }
  ],
  "differences": [
    {
      "point": "Britannica defines engine narrowly as a compound machine of mechanical powers, while Wikipedia defines it broadly as a machine converting energy into mechanical energy.",
      "quote_britannica": "ENGINE, Sì mechanics, its a compound machine, made of one or more mechanical powers, as levers, pullies, ferws, &. in order to raise, cat, or fulanany any weight, or produce any effect which could not be easily effected otherwise.",
      "quote_wikipedia": "An engine or motor is a machine designed to convert one or more forms of energy into mechanical energy."
    },
    {
      "point": "Britannica treats engine as a general mechanical contrivance, whereas Wikipedia distinguishes engines from motors in engineering jargon.",
      "quote_britannica": "The word is formed of the French reign, from the Latin ingeniums witst by England reason of the ingenuity required in the contrivance of engines to augment the effect of moving powers.",
      "quote_wikipedia": "In some engineering jargons, the two words have different meanings, in which engine is a device that burns or otherwise consumes fuel, changing its chemical composition, and a motor is a device driven by electricity, air, or hydraulic pressure, which does not change the chemical composition of its energy source."
    },
    {
      "point": "Britannica lists specific engine types such as pile and fire engines, while Wikipedia covers internal combustion, electric, and rocket engines.",
      "quote_britannica": "ENGINS for extingufliling Fires. See HYBROSTA- tics, n°3 Pile-EgGins, one convirted for driving piles. See Pix- Engine.",
      "quote_wikipedia": "Unlike internal combustion engines, a reaction engine (such as a jet engine) produces thrust by expelling reaction mass, in accordance with Newton's third law of motion."
    },
    {
      "point": "Britannica describes engineers as military experts designing fortifications, while Wikipedia focuses on the historical development of engines as machines.",
      "quote_britannica": "ENGINEEN, in the military arts, an able expert man, who, by a perfect knowledge in mathematics, delineates upon paper, or marks upon the ground, all sorts of forms, and other works proper for officers and defence.",
      "quote_wikipedia": "Simple machines, such as the club and oar (examples of the lever), are prehistoric. More complex engines using human power, animal power, water power, wind power and even steam power date back to antiquity."
    }
  ],
  "claims": [
    {
      "claim": "An engine is a compound machine made of one or more mechanical powers such as levers, pullies, and screws.",
      "tag": "renamed",
      "quote_britannica": "ENGINE, Sì mechanics, its a compound machine, made of one or more mechanical powers, as levers, pullies, ferws, &. in order to raise, cat, or fulanany any weight, or produce any effect which could not be easily effected otherwise.",
      "quote_wikipedia": "An engine or motor is a machine designed to convert one or more forms of energy into mechanical energy."
    },
    {
      "claim": "The word engine comes from the French and Latin ingenium, relating to ingenuity.",
      "tag": "enduring",
      "quote_britannica": "The word is formed of the French reign, from the Latin ingeniums witst by England reason of the ingenuity required in the contrivance of engines to augment the effect of moving powers.",
      "quote_wikipedia": "The word engine derives from Old French engin, from the Latin ingenium –the root of the word ingenious."
    },
    {
      "claim": "States engines raise water by fire or by the force of water turned into steam.",
      "tag": "enduring",
      "quote_britannica": "States Engins, a machine to raise water by fire, or rather by the force of water turned into fleam. See States Engine.",
      "quote_wikipedia": "The Watt steam engine was the first type of steam engine to make use of steam at a pressure just above atmospheric to drive the piston helped by a partial vacuum."
    },
    {
      "claim": "Fire engines are used for extinguishing fires.",
      "tag": "enduring",
      "quote_britannica": "ENGINS for extingufliling Fires. See HYBROSTA- tics, n°3 Pile-EgGins, one convirted for driving piles. See Pix- Engine.",
      "quote_wikipedia": "In this manner, a fire engine in its original form was merely a water pump, with the engine being transported to the fire by horses."
    },
    {
      "claim": "Pile engines are used for driving piles.",
      "tag": "enduring",
      "quote_britannica": "ENGINS for extingufliling Fires. See HYBROSTA- tics, n°3 Pile-EgGins, one convirted for driving piles. See Pix- Engine.",
      "quote_wikipedia": null
    },
    {
      "claim": "Engineers are military experts who delineate forms and works for offence and defence using mathematics.",
      "tag": "dropped",
      "quote_britannica": "ENGINEEN, in the military arts, an able expert man, who, by a perfect knowledge in mathematics, delineates upon paper, or marks upon the ground, all sorts of forms, and other works proper for officers and defence.",
      "quote_wikipedia": null
    },
    {
      "claim": "Engineers discover defects of a place and find remedies, and they know how to attack and defend it.",
      "tag": "dropped",
      "quote_britannica": "He should understand the art of artificition, lo as to be abb, not only to discover the defects of a place, but to find a remedy proper for them. as allow how to make an attack upon, as well as to defend, the place.",
      "quote_wikipedia": null
    },
    {
      "claim": "Engineers delineate lines of circumvallation and countervallation and lay out trenches, places of arms, batteries, and mines.",
      "tag": "dropped",
      "quote_britannica": "Their bulind is also to delineate the lines of circumval-lation and countervaltions, taking all the advantages of the ground, to mold out the treaches, places of arms, batteries, and Indigenous, taking care that none of their works be flanked or discovered from the place.",
      "quote_wikipedia": null
    }
  ],
